#!/bin/sh
# Build the sqlite3 command-line shell for TVM (unpatched upstream, built
# from the amalgamation generated in the build dir).
#
# usage: build_sqlite.sh <srcdir> <builddir> <linenoise-srcdir>
# env:   CC (the target compiler, e.g. ios-cc.sh when cross-compiling),
#        TVM_IOS_CROSS=1 when building for iOS
#
# Two stages:
#
#  1. Amalgamation. The sqlite git tree ships no sqlite3.c/shell.c: they are
#     generated by its own configure (autosetup) + `make sqlite3.c shell.c`.
#     That runs out of tree in $BUILDDIR/gen with the *host* compiler, since
#     everything it compiles is a build-time code generator (lemon,
#     mkkeywordhash, src-verify and the in-tree JimTCL jimsh that runs the
#     .tcl generators -- no system tclsh is needed). The submodule stays
#     untouched. The generated Makefile is used for nothing else: sqlite's
#     configure probes the host, not the target, so none of its results
#     (sqlite_cfg.h, OPT_FEATURE_FLAGS) feed the target compile below.
#
#  2. Target compile. sqlite3.c, shell.c and linenoise.c are compiled with
#     $CC and an explicit, platform-independent define set (see TVM_DEFS),
#     linked as the `sqlite3` executable (converted to libsqlite.dylib for
#     the Flutter apps by third_party/CMakeLists.txt, add_shared_lib).
#
# Line editing is linenoise (third_party/linenoise, BSD-2), compiled in as a
# third object: the shell's own fallback is fgets() with no editing or
# history, and readline/editline would be another dylib dependency (loaded
# images may depend on libSystem only). Not a tty, or TERM=dumb: linenoise
# reads plain lines, so scripts and pipes are unaffected.
set -e
SRCDIR="$1"
BUILDDIR="$2"
LINENOISE="$3"
. "$(cd "$(dirname "$0")" && pwd)/tvm_stamp.sh"
tvm_stamp_begin "$BUILDDIR" "$0" "$SRCDIR" "$LINENOISE" "$(cd "$(dirname "$0")/.." && pwd)/third_party/include-shim/tvm_ios_libc.h"
CC="${CC:-cc}"

GEN="$BUILDDIR/gen"
OBJ="$BUILDDIR/objects"
INCLUDE_SHIM="$(cd "$(dirname "$0")/.." && pwd)/third_party/include-shim"

# ── 1. amalgamation (host tools) ──
# CC/CC_FOR_BUILD pinned to the host cc: the environment carries the target
# compiler (ios-cc.sh on iOS) and autosetup would otherwise build lemon and
# jimsh for the device. --disable-tcl: no TCL extension, no test harness
# (the code generators use the in-tree jimsh regardless). --disable-readline
# --disable-editline: the line-editing probe is irrelevant here (stage 2
# decides), and without them configure could pick a host library up.
mkdir -p "$GEN"
cd "$GEN"
if [ ! -f Makefile ]; then
    CC=cc CC_FOR_BUILD=cc CFLAGS= LDFLAGS= \
    "$SRCDIR/configure" --disable-tcl --disable-readline --disable-editline
fi
make CC=cc sqlite3.c shell.c

# ── 2. target compile ──
# Feature set: upstream's own shell build (OPT_FEATURE_FLAGS + SHELL_OPT in
# the generated Makefile) plus FTS5 and DBSTAT, i.e. everything that lives
# in the amalgamation itself. JSON is built in unless SQLITE_OMIT_JSON.
#  SQLITE_OMIT_LOAD_EXTENSION: no dlopen in a TVM image, so `.load` and
#     load_extension() do not exist (asserted below).
#  SQLITE_MAX_WORKER_THREADS=0: with SQLITE_THREADSAFE=1 sqlite would default
#     to 8 sorter threads; the shell needs none and every pthread_create is
#     a guest thread TVM has to manage.
#  SQLITE_ENABLE_LOCKING_STYLE=0: os_unix.c turns Apple's locking-style
#     machinery on by default (fstatfs-driven choice between POSIX, AFP,
#     flock, dotfile and proxy locking, gethostuuid for the proxy files;
#     gethostuuid is unavailable on iOS). TVM's fcntl() emulates POSIX record
#     locks between its tasks, so plain POSIX locking (unixIoMethods) is
#     wanted on every platform, macOS and iOS alike.
#  HAVE_USLEEP, HAVE_LOCALTIME_R, HAVE_GMTIME_R: what the host configure
#     detected and the target (same libc) has. HAVE_FDATASYNC is deliberately
#     absent: os_unix.c then #defines fdatasync to fsync, which TVM
#     interposes (fdatasync it does not, and a raw fdatasync(fd) would sync
#     the wrong host descriptor).
#  HAVE_LINENOISE=1: the antirez API (=2 is the msteveb fork).
#  SQLITE_HAVE_ZLIB: `.archive`/zipfile()/sqlar; libz is already a
#     dependency of libtvm (dropbear, toybox).
TVM_DEFS="-DSQLITE_THREADSAFE=1 -DSQLITE_MAX_WORKER_THREADS=0 \
-DSQLITE_OMIT_LOAD_EXTENSION=1 \
-DSQLITE_ENABLE_LOCKING_STYLE=0 \
-DHAVE_USLEEP=1 -DHAVE_LOCALTIME_R=1 -DHAVE_GMTIME_R=1 -DHAVE_ISNAN=1 \
-DSQLITE_ENABLE_MATH_FUNCTIONS -DSQLITE_ENABLE_PERCENTILE \
-DSQLITE_ENABLE_FTS4 -DSQLITE_ENABLE_FTS5 \
-DSQLITE_ENABLE_RTREE -DSQLITE_ENABLE_GEOPOLY \
-DSQLITE_ENABLE_DBSTAT_VTAB -DSQLITE_ENABLE_DBPAGE_VTAB \
-DSQLITE_ENABLE_STMTVTAB -DSQLITE_ENABLE_BYTECODE_VTAB \
-DSQLITE_ENABLE_EXPLAIN_COMMENTS -DSQLITE_ENABLE_OFFSET_SQL_FUNC \
-DSQLITE_ENABLE_UNKNOWN_SQL_FUNCTION \
-DSQLITE_DQS=0 -DSQLITE_STRICT_SUBTYPE=1 -DSQLITE_HAVE_ZLIB=1 \
-DHAVE_LINENOISE=1"

TVM_CFLAGS="-g -gdwarf-4"
SHELL_CFLAGS="$TVM_CFLAGS"
if [ -n "$TVM_IOS_CROSS" ]; then
    # The iPhoneOS SDK marks system(3) unavailable and shell.c calls it
    # (.shell/.system, the edit() SQL function); TVM interposes it. Bind the
    # call to the symbol through the same force-included header toybox and
    # less use. popen(3) is only __swift_unavailable there, so it compiles.
    SHELL_CFLAGS="$TVM_CFLAGS -include $INCLUDE_SHIM/tvm_ios_libc.h"
fi

rm -rf "$OBJ"
mkdir -p "$OBJ"
# sqlite3.c does not use HAVE_LINENOISE; passing the one define set to both
# keeps them configured alike (the same TVM_DEFS go on upstream's link line).
"$CC" $TVM_CFLAGS $TVM_DEFS -I"$GEN" -c "$GEN/sqlite3.c" -o "$OBJ/sqlite3.o"
"$CC" $SHELL_CFLAGS $TVM_DEFS -I"$GEN" -I"$LINENOISE" -c "$GEN/shell.c" -o "$OBJ/shell.o"
"$CC" $TVM_CFLAGS -c "$LINENOISE/linenoise.c" -o "$OBJ/linenoise.o"

# Build-time assertions: no extension loading and nothing that needs dlopen.
if nm "$OBJ/sqlite3.o" | grep -Eq ' T _?sqlite3_load_extension$'; then
    echo "error: sqlite3 was built with extension loading (SQLITE_OMIT_LOAD_EXTENSION missing)" >&2
    exit 1
fi
if nm -u "$OBJ"/*.o | grep -Eq '(^| )_?dlopen$'; then
    echo "error: sqlite3 objects reference dlopen" >&2
    exit 1
fi

# The executable. -lm for the math functions, -lz for the archive/zipfile
# code.
"$CC" -g -o "$BUILDDIR/sqlite3" "$OBJ"/*.o -lm -lz
